	/**
	 * A SILENT result must be returned before its remote source is consumed, so the outer query timer can cancel it.
	 */
	@Test
	public void silentServiceEvaluationReturnsBeforeRemoteConsumptionAndHonorsMaxExecutionTime() throws Exception {
		ResultControl control = new ResultControl(ResultMode.BLOCK);
		addServiceData(1);
		useService(new RepositoryFederatedService(new ControlledRepository(serviceRepo, control), false));

		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<TupleQueryResult> evaluation = null;
		TupleQueryResult result = null;
		RepositoryConnection conn = localRepo.getConnection();
		try {
			TupleQuery query = conn.prepareTupleQuery(
					"SELECT ?s WHERE { SERVICE SILENT <urn:dummy> { ?s ?p ?o } }");
			query.setMaxExecutionTime(1);

			evaluation = executor.submit((Callable<TupleQueryResult>) query::evaluate);
			result = evaluation.get(2, TimeUnit.SECONDS);
			assertEquals(0, control.hasNextCalls.get(), "evaluation must not consume the remote result");

			Future<Boolean> hasNext = executor.submit((Callable<Boolean>) result::hasNext);
			await(control.started, "remote result consumption");
			await(control.closed, "remote result close after query timeout");
			ExecutionException failure = assertThrows(ExecutionException.class,
					() -> hasNext.get(5, TimeUnit.SECONDS));
			assertTrue(failure.getCause() instanceof QueryInterruptedException,
					"query timeout must propagate instead of becoming SILENT pass-through: " + failure);
		} finally {
			control.release();
			if (result != null) {
				result.close();
			}
			if (evaluation != null) {
				evaluation.cancel(true);
			}
			shutdownExecutor(executor);
			conn.close();
		}
	}

	/** Closing a lazy direct SILENT result before reading it must leave an unopened source untouched. */
